import{d as p,C as a,o as d,c as g,a3 as s,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十八章","description":"《正易心法》第二十八章——乾坤六子，其象与数：象上坤加乾画生三男、乾加坤画生三女；数上乾三巽离兑四震坎艮五坤六，坤六震坎艮七巽离兑八乾九；乾坤在外，六子包于其中。","frontmatter":{"title":"正易心法·第二十八章","description":"《正易心法》第二十八章——乾坤六子，其象与数：象上坤加乾画生三男、乾加坤画生三女；数上乾三巽离兑四震坎艮五坤六，坤六震坎艮七巽离兑八乾九；乾坤在外，六子包于其中。","category":"guide","aliases":["正易心法第二十八章","乾坤六子其象与数","乾坤之位皆包六子"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-28.md","filePath":"yijing/zheng-yi-xin-fa/chapter-28.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-28.md"},x=p({...c,setup(b){const o=[{id:"z28-01",label:"一、其象与数",showLabel:!0,sentences:[["乾坤六子，其",{text:"象与数",glossary:"xiangYuShu"},"。乾坤之位，皆包六子。"]],note:["乾坤与六子的关系，要从象和数两个角度来看：乾坤的位置（范围），都包含了六子在其中。（**本章从第十九章「入位生六子」再进一步**：第九章说六子怎么生，本章说从象、数两方面都能看出「乾坤包六子」——**乾坤是边界，六子在中间。**）"]},{id:"z28-02",label:"二、象上包六子",showLabel:!0,sentences:[["象谓坤卦上中下加三乾画，便生",{text:"三男",glossary:"sannan"},"。以乾卦上中下加三坤画，便生",{text:"三女",glossary:"sannv"},"。"]],note:["从象来说：坤卦的上、中、下三个位置，分别加入一根阳爻，就生出了三男（震、坎、艮）；以乾卦的上、中、下三个位置，分别加入一根阴爻，就生出了三女（巽、离、兑）。（**这是第九章「破体」的列表式重述**：坤体被破三次得三男（阳少阴多），乾体被破三次得三女（阴少阳多）——**六子都是「二与一」的比例，唯乾坤是「纯」。**）"]},{id:"z28-03",label:"三、象上乾坤在外",showLabel:!0,sentences:[["乾坤之体，皆在外，六子皆包于其中也。"]],note:["乾坤的卦体处于两端，六子都包含在其中。（**「在外」是空间关系**：乾坤＝纯阳／纯阴＝两端／边界，六子＝混杂＝中间／内部。**这就在象上印证了第二十章「乾坤真体、六子假合」：真体包含假合，边界生成中间。**）"]},{id:"z28-04",label:"四、数上包六子",showLabel:!0,sentences:[["数谓若画乾数三，巽离兑四，震坎艮五，坤六。坤数六，震坎艮七，巽离兑八，乾九。"]],note:["从数来说：画乾卦，数为三；巽、离、兑各为四；震、坎、艮各为五；坤卦为六。反过来，坤数为六，震、坎、艮各为七，巽、离、兑各为八，乾为九。（**计数方式是「阳爻一画、阴爻两画」**：乾＝3×1＝3；巽离兑＝2×1＋1×2＝4；震坎艮＝1×1＋2×2＝5；坤＝3×2＝6。**反向从坤起：每加一阳爻加一**，故坤6、震坎艮7、巽离兑8、乾9。**坤（6）成了两组数列的中心对称点。**）"]},{id:"z28-05",label:"五、象之自然",showLabel:!0,sentences:[["乾坤之策皆在外，六子皆包于其中也。此象之自然，有不可得而",{text:"容心",glossary:"rongxin"},"者。"]],note:["乾坤的策数处于两端，六子都包含在其中。这是卦象的自然规律，有不可以用人为安排来解释的自然性。（**「容心」是宋人口语，意为「用心思去安排、干预」**。麻衣三章连说「非容心」：第二十四章「羲皇画卦，非出私意」、第二十六章「气序自然」、本章「象之自然，有不可得而容心者」——**《易》的一切结构都是自然之理的自然呈现，「容心」恰恰是理解《易》的最大障碍。**）"]}],r=[{id:"xiangYuShu",term:"其象与数",pinyin:"qí xiàng yǔ shù",meaning:"从象（卦画结构）和数（爻画数量）两个角度来看。"},{id:"sannan",term:"三男",pinyin:"sān nán",meaning:"震（长男）、坎（中男）、艮（少男）——坤体被一阳所破而生。"},{id:"sannv",term:"三女",pinyin:"sān nǚ",meaning:"巽（长女）、离（中女）、兑（少女）——乾体被一阴所破而生。"},{id:"rongxin",term:"容心",pinyin:"róng xīn",meaning:"用心思去安排、干预。「不可得而容心」即不可以人为安排解释。"}];return(u,t)=>{const i=a("DaoTextReading"),l=a("DaoKeywordCards");return d(),g("div",null,[t[0]||(t[0]=s(`<h1 id="正易心法·第二十八章" tabindex="-1">正易心法·第二十八章 <a class="header-anchor" href="#正易心法·第二十八章" aria-label="Permalink to &quot;正易心法·第二十八章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章从<strong>象与数</strong>两个角度，证明<strong>乾坤包含六子</strong>：</p><p><strong>象的证明</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>坤加一阳 → 三男（震、坎、艮）</span></span>
<span class="line"><span>乾加一阴 → 三女（巽、离、兑）</span></span>
<span class="line"><span>乾坤在两端，六子在中间</span></span></code></pre></div><p><strong>数的证明</strong>（阳爻一画、阴爻两画）：</p><table tabindex="0"><thead><tr><th>卦</th><th>计数</th><th>数</th></tr></thead><tbody><tr><td>乾</td><td>3×1</td><td><strong>3</strong></td></tr><tr><td>巽离兑</td><td>2×1+1×2</td><td><strong>4</strong></td></tr><tr><td>震坎艮</td><td>1×1+2×2</td><td><strong>5</strong></td></tr><tr><td>坤</td><td>3×2</td><td><strong>6</strong></td></tr><tr><td>震坎艮（反向）</td><td>6+1</td><td><strong>7</strong></td></tr><tr><td>巽离兑（反向）</td><td>6+2</td><td><strong>8</strong></td></tr><tr><td>乾（反向）</td><td>6+3</td><td><strong>9</strong></td></tr></tbody></table><p><strong>结论</strong>：<strong>象与数，结论完全一致——乾坤在外（两端），六子在内（中间）。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「坤（6）是中心对称点」</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾(3) ←→ 乾(9)</span></span>
<span class="line"><span>巽离兑(4) ←→ 巽离兑(8)</span></span>
<span class="line"><span>震坎艮(5) ←→ 震坎艮(7)</span></span>
<span class="line"><span>坤(6) ←→ 坤(6)</span></span></code></pre></div><p><strong>这正是第二十章「乾坤真体，六子假合」在象数层面的具体证明</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾坤在外（边界、真体）</span></span>
<span class="line"><span>六子在内（被包含、假合）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>真体包含假合，边界生成中间</span></span>
<span class="line"><span>= 乾坤是六子的父母，不只是比喻，而是象数上可以验证的结构</span></span></code></pre></div><p><strong>「有不可得而容心者」</strong>——三章连说「非容心」：</p><table tabindex="0"><thead><tr><th>章</th><th>说法</th></tr></thead><tbody><tr><td>第二十四章</td><td>羲皇画卦，非出私意</td></tr><tr><td>第二十六章</td><td>气序自然，非圣人固以次之</td></tr><tr><td>第二十八章</td><td>此象之自然，有不可得而容心者</td></tr></tbody></table><p><strong>《易》的一切结构——卦象、卦序、象数关系——都不是人为设计的；「容心」（人为干预）恰恰是理解《易》的最大障碍。</strong></p><p><strong>象与数为何要并列论证？</strong></p><table tabindex="0"><thead><tr><th></th><th>特点</th><th>可能被质疑</th></tr></thead><tbody><tr><td><strong>象</strong>（卦画结构）</td><td>直观可见，形象具体</td><td>「凑巧」</td></tr><tr><td><strong>数</strong>（爻画数值）</td><td>抽象精确，数量关系</td><td>「人为计算」</td></tr></tbody></table><p><strong>两者同时指向同一结论 = 不是凑巧，也不是人为，是真正的「象之自然」。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把「象」的证明自己画一遍（坤加阳、乾加阴）；</li><li>再算一遍「数」：<strong>阳爻一画、阴爻两画</strong>，看是不是 3、4、5、6、7、8、9；</li><li>最后读「不可得而容心」——<strong>这是本章的落点。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>其象与数</strong>：从两个角度证明同一结论。</li><li><strong>象上</strong>：坤加阳生三男，乾加阴生三女。</li><li><strong>乾坤在外</strong>：六子包于其中。</li><li><strong>数上</strong>：乾三、巽离兑四、震坎艮五、坤六；坤六、震坎艮七、巽离兑八、乾九。</li><li><strong>象之自然</strong>：有不可得而容心者。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,24)),e(i,{colophon:"其象与数 · 乾坤在外 · 六子包中 · 不可容心",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十八章原文",sections:o,glossary:r}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。本章「数」按「阳爻一画、阴爻两画」的计法，读者可自行核对。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"其象与数",pinyin:["xiàng","shù"],meaning:"从象（卦画结构）与数（爻画数量）两方面论证同一结论——双向印证，故非凑巧亦非人为。"},{term:"三男三女",pinyin:["sān","nán"],meaning:"坤加一阳生震坎艮（三男），乾加一阴生巽离兑（三女）——六子皆是「二与一」的比例。"},{term:"乾坤在外",pinyin:["qián","kūn"],meaning:"象上：乾坤是纯体，处在两端；数上：乾3/9、坤6，也在两端。六子皆包于其中。"},{term:"策数序列",pinyin:["cè","shù"],meaning:"乾3、巽离兑4、震坎艮5、坤6；坤6、震坎艮7、巽离兑8、乾9。坤（6）是中心对称点。"},{term:"不可得而容心",pinyin:["róng","xīn"],meaning:"「容心」＝用心思去安排。三章连说「非容心」，是麻衣反对人为解释的核心立场。"}]}),t[3]||(t[3]=s(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章从<strong>象与数</strong>两个角度证明乾坤包含六子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>象：坤加一阳生三男、乾加一阴生三女 → 乾坤在两端，六子在中间</span></span>
<span class="line"><span>数：乾3、巽离兑4、震坎艮5、坤6；坤6、震坎艮7、巽离兑8、乾9</span></span>
<span class="line"><span>    → 乾坤在两端，六子在中间</span></span></code></pre></div><p><strong>结论：象与数完全一致——乾坤在外，六子在内。</strong></p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>这与第二十章的关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二十章（哲学层面）：乾坤真体，六子假合</span></span>
<span class="line"><span>第二十八章（象数层面）：乾坤在外，六子在内</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两章合读：</span></span>
<span class="line"><span>  第二十章说「为什么」——乾坤是真体，所以六子是假合</span></span>
<span class="line"><span>  第二十八章说「怎么看」——从象数上可以直接验证</span></span>
<span class="line"><span>                             哲学命题 → 象数验证 = 义理与象数相互印证</span></span></code></pre></div><p><strong>「坤（6）是中心对称点」</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾(3) ←→ 乾(9)</span></span>
<span class="line"><span>巽离兑(4) ←→ 巽离兑(8)</span></span>
<span class="line"><span>震坎艮(5) ←→ 震坎艮(7)</span></span>
<span class="line"><span>坤(6) ←→ 坤(6)</span></span></code></pre></div><p><strong>象与数为何要并列论证？</strong></p><table tabindex="0"><thead><tr><th></th><th>特点</th><th>可能被质疑</th></tr></thead><tbody><tr><td>象</td><td>直观可见，形象具体</td><td>可能被质疑为「凑巧」</td></tr><tr><td>数</td><td>抽象精确，数量关系</td><td>可能被质疑为「人为计算」</td></tr></tbody></table><p><strong>两者同时指向同一结论 = 不是凑巧，也不是人为。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li><strong>动手算一遍</strong>：阳爻一画、阴爻两画，看是不是 3、4、5、6、7、8、9；</li><li>记住「坤（6）是中心」，<strong>它是唯一从两个方向数都一样的卦</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>「自然之理」需要被论证吗？</strong> 麻衣花了整整一章算象与数，来证明「不可容心」——<strong>这本身不就是一种「容心」？</strong> 我的看法：<strong>不是。</strong> 差别在于：<strong>「容心」是「先定结论再凑数」，「论证」是「把已经在那里的结构显出来」。</strong> 判据很简单：<strong>如果在论证过程中，你需要删掉不合的数据，那就是容心；如果只是把数据排列出来，就是揭示。</strong> 麻衣的做法是后者——<strong>他列出了全部八个卦的数，没有一个被省略。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>乾坤与六子的关系，要从象和数两个角度来看：乾坤的位置（范围），都包含了六子在其中。</p><p>从象来说：坤卦的上、中、下三个位置，分别加入一根阳爻，就生出了三男（震、坎、艮）；以乾卦的上、中、下三个位置，分别加入一根阴爻，就生出了三女（巽、离、兑）。乾坤的卦体处于两端，六子都包含在其中。</p><p>从数来说：画乾卦，数为三；巽、离、兑各为四；震、坎、艮各为五；坤卦为六。反过来，坤数为六，震、坎、艮各为七，巽、离、兑各为八，乾为九。乾坤的策数处于两端，六子都包含在其中。</p><p>这是卦象的自然规律，有不可以用人为安排来解释的自然性。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十八章是「乾坤包六子」的一次双证——<strong>从画上看是这样，从数上看也是这样；两条路走到同一个地方，才叫自然。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「象与数」双证的必要性</strong>——<strong>只用象，人家说「凑巧」；只用数，人家说「算的」。</strong> 两条路同时到，才没有话讲。<strong>这是麻衣的论证风格：不靠单一角度。</strong></li><li><strong>「坤（6）是中心」</strong>——很有意思：<strong>从坤往两边数，一边是 6、7、8、9（加阳），一边是 6、5、4、3（减阴），完全对称。</strong> 坤不是「最末」，是<strong>分界点</strong>。</li><li><strong>「阳爻一画、阴爻两画」</strong>——这个计法的来历值得想：<strong>阴爻是两个短横，本来就占两笔。</strong> 麻衣没有发明规则，他是<strong>照着笔画本身在数</strong>。<strong>这也是「不可容心」的一个小例子：规则是从物件本身来的，不是先定规则再套。</strong></li><li><strong>「不可得而容心者」</strong>——这是本章最重的一句，而且它是<strong>三章连说的第三次</strong>（第二十四、二十六、二十八章）。<strong>麻衣反复讲同一件事，说明这是他最在意的地方。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「自然之理」需要被论证吗？论证「自然」，算不算一种「容心」？</strong> 我的看法：<strong>不算。</strong> 差别在于：<strong>「容心」是先定结论再凑数，「论证」是把已经在那里的结构显出来。</strong> 判据很简单：<strong>论证过程中你有没有偷偷删掉不合的数据。</strong> 麻衣列出了全部八个卦的数，<strong>一个没省——这就是「不可得而容心」的实践。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-09">第九章 · 乃生六子</a> — 破体生六子（本章的象上重述）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-20">第二十章 · 唯乾与坤</a> — 乾坤真体（本章的象数验证）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-24">第二十四章 · 见于日用</a> — 「非出私意」（本章呼应）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-26">第二十六章 · 有本有余</a> — 「气序自然」（本章呼应）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-29">第二十九章</a> — 爻数三百八十四（由本章象数之法推出天文）</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「乾，天也，故称乎父；坤，地也，故称乎母」</li></ul>`,26))])}}});export{y as __pageData,x as default};
